async function withTempCwd<T>(fn: () => Promise<T>): Promise<T> {
  const previous = process.cwd();
  const dir = mkdtempSync(join(tmpdir(), 'tally-cli-cwd-'));
  process.chdir(dir);
  try {
    return await fn();
  } finally {
    process.chdir(previous);
  }
}

